using System;using System.Linq;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {public static class TrainClutch {
 public static double OuterRadius(double mean,double inner){double lo=inner,hi=mean*2;for(int i=0;i<70;i++){double r=(lo+hi)/2,value=2*(r*r*r-inner*inner*inner)/(3*(r*r-inner*inner));if(value<mean)lo=r;else hi=r;}return (lo+hi)/2;}
 public static void Add(TransmissionTrain t,TrainSolution s){var c=t.Overload;if(c==null||!c.ClutchEnabled)return;var a=s.Scene.Model;var l=s.Compound;double z=l.Height,shaft=l.OutputDiameter/2,ri=c.MeanRadius*.6,ro=OuterRadius(c.MeanRadius,ri),gap=t.SharedHousing.Clearance,baseR=l.Diameter/2;if(ri<shaft+1||ro+2+gap>baseR-t.SharedHousing.Wall)throw new Exception("Муфта: радиус трения не помещается между валом и стенкой корпуса. Измените средний радиус.");var drive=a.Parts.First(p=>p.Id.EndsWith("_SH_OUTPUT_CARRIER"));drive.Sections.Last().Outer=CadLoop.Round(0,0,ro+1);drive.Sections.Last().Holes.Clear();drive.Label="Водило, вал и ведущий диск муфты";double packet=c.Surfaces*.5,drivenBottom=z+4+packet,drivenTop=drivenBottom+4,springTop=drivenTop+6,coverTop=springTop+18;var studHoles=a.Parts.First(p=>p.Id=="SH_COVER").Sections[0].Holes.Skip(1).ToArray();Func<double,CadLoop> circle=r=>CadLoop.Round(0,0,r);Func<CadLoop> outside=()=>t.SharedHousing.Shape=="Round"?circle(baseR):TransmissionGeometry.Rect(-baseR,-baseR,baseR,baseR);Func<string,string,string,CadLoop,double,double,IEnumerable<CadLoop>,CadPart> part=(id,name,role,outer,bottom,top,holes)=>{var p=new CadPart(id,name,role,role=="housing"?TransmissionGeometry.Case:TransmissionGeometry.Steel);p.Sections.Add(new CadSection(bottom,top,outer,holes));a.Parts.Add(p);return p;};
  part("SH_CLUTCH_MODULE","Модуль предохранительной муфты","housing",outside(),z,springTop,new[]{circle(ro+1+gap)}.Concat(studHoles));var pack=part("SH_CLUTCH_FRICTION","Габарит фрикционного пакета · поверхности заданы","friction",circle(ro),z+4,drivenBottom,new[]{circle(ri)});pack.Note="Rср=2(Ro³−Ri³)/(3(Ro²−Ri²)), равномерное давление. Пакет показан габаритом; шлицы дисков, износ и осевая фиксация требуют деталировки.";
  var driven=part("SH_CLUTCH_OUTPUT","Ведомый диск и выходной фланец муфты","shaft",circle(ro+1),drivenBottom,drivenTop,null);driven.Sections.Add(new CadSection(drivenTop,coverTop+gap,circle(shaft),null));driven.Sections.Add(new CadSection(coverTop+gap,coverTop+4,circle(Math.Max(12,shaft+6)),null));var cover=part("SH_CLUTCH_COVER","Крышка и две опоры ведомого вала","housing",outside(),springTop,coverTop,new[]{circle(shaft+gap)}.Concat(studHoles));cover.Sections.Clear();double bearingD=Math.Max(l.OutputDiameter+8,22),bw=7;var bounds=new[]{springTop,springTop+1,springTop+1+bw,springTop+10,springTop+10+bw,coverTop};for(int i=0;i<bounds.Length-1;i++)cover.Sections.Add(new CadSection(bounds[i],bounds[i+1],outside(),new[]{circle(i==1||i==3?bearingD/2+gap:shaft+gap)}.Concat(studHoles)));for(int i=0;i<2;i++){double bottom=springTop+(i==0?1:10);part("SH_CLUTCH_BEARING_"+(i+1),"Опора ведомого вала муфты · габарит","bearing",circle(bearingD/2),bottom,bottom+bw,new[]{circle(shaft)});}var spring=part("SH_CLUTCH_SPRING","Габарит пружины · усилие задано","spring",circle(shaft+4),drivenTop,springTop,new[]{circle(shaft+gap)});spring.Note="Габаритный образец; жёсткость, напряжения, рабочий ход и устойчивость пружины не рассчитаны.";
  var last=s.States[CompoundReducer.Ordered(t).Last().Id];foreach(var p in new[]{driven,pack})s.Scene.TrainMotions[p.Id]=new TrainMotion{Source=new PartMotion{Kind="input",Result=new Result{P=new Parameters()}},Gain=last.OutputGain,Frame=Matrix3D.Identity,Inverse=Matrix3D.Identity};double extension=coverTop-z;foreach(var p in a.Parts.Where(p=>p.Id.StartsWith("SH_STUD_")))p.Sections[0].Top+=extension;foreach(var p in a.Parts.Where(p=>p.Id.StartsWith("SH_NUT_")&&p.Id.EndsWith("_1")))p.Placement.Translate(new Vector3D(0,0,extension));l.Height=coverTop;l.OutputPlane=coverTop+4;l.Support1=springTop+1+bw/2;l.Support2=springTop+10+bw/2;last.OutputFrame=RobotMath.Translation(0,0,l.OutputPlane);s.Notes.Add("Муфта: отдельный геометрический модуль. Пакет трения и пружина показаны габаритами, крепление дисков и осевая фиксация не разработаны. Скорость реального проскальзывания из статического момента не определяется.");
 }
}}
